10	/// Copies the Windows desktop embedding files to the copy directory.
11	class UnpackWindows extends Target {
12	  const UnpackWindows();
13	
14	  @override
15	  String get name => 'unpack_windows';
16	
17	  @override
18	  List<Source> get inputs => const <Source>[
19	    Source.pattern('{FLUTTER_ROOT}/packages/flutter_tools/lib/src/build_system/targets/windows.dart'),
20	    Source.artifact(Artifact.windowsDesktopPath, mode: BuildMode.debug),
21	  ];
22	
23	  @override
24	  List<Source> get outputs => const <Source>[
25	    Source.pattern('{PROJECT_DIR}/windows/flutter/flutter_windows.dll'),
26	    Source.pattern('{PROJECT_DIR}/windows/flutter/flutter_windows.dll.exp'),
27	    Source.pattern('{PROJECT_DIR}/windows/flutter/flutter_windows.dll.lib'),
28	    Source.pattern('{PROJECT_DIR}/windows/flutter/flutter_windows.dll.pdb'),
29	    Source.pattern('{PROJECT_DIR}/windows/flutter/flutter_export.h'),
30	    Source.pattern('{PROJECT_DIR}/windows/flutter/flutter_messenger.h'),
31	    Source.pattern('{PROJECT_DIR}/windows/flutter/flutter_plugin_registrar.h'),
32	    Source.pattern('{PROJECT_DIR}/windows/flutter/flutter_windows.h'),
33	    Source.pattern('{PROJECT_DIR}/windows/flutter/icudtl.dat'),
34	  ];
35	
36	  @override
37	  List<Target> get dependencies => const <Target>[];
38	
39	  @override
40	  Future<void> build(Environment environment) async {
41	    // This path needs to match the prefix in the rule below.
42	    final String basePath = environment.artifacts
43	      .getArtifactPath(Artifact.windowsDesktopPath);
44	    for (final File input in environment.fileSystem.directory(basePath)
45	        .listSync(recursive: true)
46	        .whereType<File>()) {
47	      final String outputPath = environment.fileSystem.path.join(
48	        environment.projectDir.path,
49	        'windows',
50	        'flutter',
51	        environment.fileSystem.path
52	          .relative(input.path, from: basePath),
53	      );
54	      final File destinationFile = environment.fileSystem.file(outputPath);
55	      if (!destinationFile.parent.existsSync()) {
56	        destinationFile.parent.createSync(recursive: true);
57	      }
58	      environment.fileSystem
59	        .file(input).copySync(destinationFile.path);
60	    }
61	  }
62	}
