16	/// The only files/subdirectories we care out.
17	const List<String> _kLinuxArtifacts = <String>[
18	  'libflutter_linux_glfw.so',
19	  'flutter_export.h',
20	  'flutter_messenger.h',
21	  'flutter_plugin_registrar.h',
