113	/// Creates a debug bundle for the Linux desktop target.
114	class DebugBundleLinuxAssets extends Target {
115	  const DebugBundleLinuxAssets();
116	
117	  @override
118	  String get name => 'debug_bundle_linux_assets';
119	
120	  @override
121	  List<Target> get dependencies => const <Target>[
122	    KernelSnapshot(),
123	    UnpackLinuxDebug(),
124	  ];
125	
126	  @override
127	  List<Source> get inputs => const <Source>[
128	    Source.pattern('{BUILD_DIR}/app.dill'),
129	    Source.pattern('{FLUTTER_ROOT}/packages/flutter_tools/lib/src/build_system/targets/linux.dart'),
130	    Source.pattern('{PROJECT_DIR}/pubspec.yaml'),
131	    ...IconTreeShaker.inputs,
132	  ];
133	
134	  @override
135	  List<Source> get outputs => const <Source>[
136	    Source.pattern('{OUTPUT_DIR}/flutter_assets/kernel_blob.bin'),
137	  ];
138	
139	  @override
140	  List<String> get depfiles => const <String>[
141	    'flutter_assets.d',
142	  ];
143	
144	  @override
145	  Future<void> build(Environment environment) async {
146	    if (environment.defines[kBuildMode] == null) {
147	      throw MissingDefineException(kBuildMode, 'debug_bundle_linux_assets');
148	    }
149	    final BuildMode buildMode = getBuildModeForName(environment.defines[kBuildMode]);
150	    final Directory outputDirectory = environment.outputDir
151	      .childDirectory('flutter_assets');
152	    if (!outputDirectory.existsSync()) {
153	      outputDirectory.createSync();
154	    }
155	
156	    // Only copy the kernel blob in debug mode.
157	    if (buildMode == BuildMode.debug) {
158	      environment.buildDir.childFile('app.dill')
159	        .copySync(outputDirectory.childFile('kernel_blob.bin').path);
160	    }
161	    final Depfile depfile = await copyAssets(environment, outputDirectory);
162	    final DepfileService depfileService = DepfileService(
163	      fileSystem: globals.fs,
164	      logger: globals.logger,
165	      platform: globals.platform,
166	    );
167	    depfileService.writeToFile(
168	      depfile,
169	      environment.buildDir.childFile('flutter_assets.d'),
170	    );
171	  }
172	}
